import {
	useSharedValue,
	withSpring,
	interpolate,
	Extrapolation,
	runOnJS,
	useAnimatedReaction
} from 'react-native-reanimated'
import { Gesture } from 'react-native-gesture-handler'
import type { SharedValue } from 'react-native-reanimated'
import { useMemo } from 'react'

const DEFAULT_MAX_SWIPE = -220
const VELOCITY_THRESHOLD = -2500
const MAX_VELOCITY = -2500
const FRAME_TIME_MS = 16.67
const MAX_DELTA_PER_FRAME = (MAX_VELOCITY * FRAME_TIME_MS) / 1000
const SWIPE_WIDTH_RATIO = 0.9
const SWIPE_DAMPING = 0.55
const MIN_DISTANCE_FOR_VELOCITY_LOCK = -100
const BUTTONS_FULLY_SCALED_THRESHOLD = -140
const THRESHOLD_MARGIN_RATIO = 0.2
const MAX_THRESHOLD_MARGIN_RATIO = 0.3
const LOCK_PROXIMITY_THRESHOLD = 10
const THRESHOLD_PROXIMITY_BUFFER = 50
const MAX_VELOCITY_FOR_LOCK = 50

const LOCK_ANIMATION_SPRING_CONFIG = {
	dampingRatio: 0.9
}

type UseProjectGroupSwipeGestureProps = {
	buttonId: string
	activeButtonId: SharedValue<string | null>
	resetTriggerId: SharedValue<string | null>
	onDelete: () => void
	onButtonLayout: (width: number) => void
	enabled: boolean
}

export const useProjectGroupSwipeGesture = ({
	buttonId,
	activeButtonId,
	resetTriggerId,
	onDelete,
	onButtonLayout,
	enabled
}: UseProjectGroupSwipeGestureProps) => {
	const translateX = useSharedValue(0)
	const editButtonScale = useSharedValue(0)
	const deleteButtonScale = useSharedValue(0)
	const deleteButtonWidth = useSharedValue(48)
	const isLocked = useSharedValue(false)
	const startX = useSharedValue(0)
	const previousTranslateX = useSharedValue(0)
	const hasTriggeredDelete = useSharedValue(false)
	const buttonWidth = useSharedValue(0)
	const maxSwipe = useSharedValue(DEFAULT_MAX_SWIPE)
	const lockThreshold = useSharedValue(DEFAULT_MAX_SWIPE)

	const resetToOriginalState = () => {
		'worklet'
		isLocked.value = false
		hasTriggeredDelete.value = false
		previousTranslateX.value = 0
		translateX.value = withSpring(0, LOCK_ANIMATION_SPRING_CONFIG)
		editButtonScale.value = withSpring(0, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonScale.value = withSpring(0, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonWidth.value = withSpring(48, LOCK_ANIMATION_SPRING_CONFIG)
		if (activeButtonId.value === buttonId) {
			activeButtonId.value = null
		}
	}

	useAnimatedReaction(
		() => resetTriggerId.value,
		(currentResetId) => {
			if (currentResetId === buttonId) {
				resetToOriginalState()
				resetTriggerId.value = null
			}
		}
	)

	const calculateDampedTranslateX = (
		newTranslateX: number,
		previousX: number
	) => {
		'worklet'
		const delta = newTranslateX - previousX
		const currentDistance = Math.abs(previousX)
		const baseResistance = 1.35
		const progressiveResistance = 1 + currentDistance / 350
		const resistanceFactor = baseResistance * progressiveResistance
		const dampedDelta = (delta * SWIPE_DAMPING) / resistanceFactor
		const cappedDelta = Math.max(dampedDelta, MAX_DELTA_PER_FRAME)
		return previousX + cappedDelta
	}

	const updateButtonScales = (cappedTranslateX: number) => {
		'worklet'
		editButtonScale.value = interpolate(
			cappedTranslateX,
			[-100, -140],
			[0, 1],
			Extrapolation.CLAMP
		)
		deleteButtonScale.value = interpolate(
			cappedTranslateX,
			[-60, -100],
			[0, 1],
			Extrapolation.CLAMP
		)
		const widthExpansionThreshold = -140
		if (cappedTranslateX > widthExpansionThreshold) {
			deleteButtonWidth.value = 48
		} else {
			const maxSwipeDistance = Math.abs(maxSwipe.value)
			const maxWidth = Math.max(48, maxSwipeDistance - 96)
			deleteButtonWidth.value = interpolate(
				cappedTranslateX,
				[widthExpansionThreshold, maxSwipe.value],
				[48, maxWidth],
				Extrapolation.CLAMP
			)
		}
	}

	const lockToThreshold = (
		threshold: number,
		velocity: number = 0,
		deleteWidth: number = 48
	) => {
		'worklet'
		isLocked.value = true
		translateX.value = withSpring(threshold, {
			...LOCK_ANIMATION_SPRING_CONFIG,
			velocity
		})
		previousTranslateX.value = threshold
		editButtonScale.value = withSpring(1, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonScale.value = withSpring(1, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonWidth.value = withSpring(
			deleteWidth,
			LOCK_ANIMATION_SPRING_CONFIG
		)
	}

	const unlockAndReset = (velocity: number = 0) => {
		'worklet'
		isLocked.value = false
		translateX.value = withSpring(0, {
			...LOCK_ANIMATION_SPRING_CONFIG,
			velocity
		})
		previousTranslateX.value = 0
		editButtonScale.value = withSpring(0, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonScale.value = withSpring(0, LOCK_ANIMATION_SPRING_CONFIG)
		deleteButtonWidth.value = withSpring(48, LOCK_ANIMATION_SPRING_CONFIG)
	}

	const calculateThresholds = (maxThreshold: number) => {
		'worklet'
		const smallerMargin =
			Math.abs(BUTTONS_FULLY_SCALED_THRESHOLD) * THRESHOLD_MARGIN_RATIO
		const maxMargin = Math.abs(maxThreshold) * MAX_THRESHOLD_MARGIN_RATIO
		return {
			smallerMin: BUTTONS_FULLY_SCALED_THRESHOLD - smallerMargin,
			smallerThreshold: BUTTONS_FULLY_SCALED_THRESHOLD,
			maxMin: maxThreshold - maxMargin,
			maxMax: maxThreshold + maxMargin,
			maxThreshold
		}
	}

	const isInGap = (x: number, maxMin: number) => {
		'worklet'
		return x < BUTTONS_FULLY_SCALED_THRESHOLD && x > maxMin
	}

	const handleButtonLayout = (width: number) => {
		if (width <= 0) return
		buttonWidth.value = width
		const maxSwipeDistance = width * SWIPE_WIDTH_RATIO
		const negativeMaxSwipe = -maxSwipeDistance
		maxSwipe.value = negativeMaxSwipe
		lockThreshold.value = negativeMaxSwipe
		onButtonLayout(width)
	}

	const panGesture = useMemo(
		() =>
			Gesture.Pan()
				.enabled(enabled)
				.activeOffsetX([-10, 10])
				.failOffsetY([-10, 10])
				.onBegin(() => {
					const currentActiveId = activeButtonId.value
					if (currentActiveId && currentActiveId !== buttonId) {
						resetTriggerId.value = currentActiveId
					}
					activeButtonId.value = buttonId
					const currentX = translateX.value
					startX.value = currentX
					previousTranslateX.value = currentX
					hasTriggeredDelete.value = false
				})
				.onUpdate((event) => {
					const newTranslateX = startX.value + event.translationX
					const isLockedState = isLocked.value
					const hasDelete = hasTriggeredDelete.value

					if (newTranslateX < 0) {
						const delta = newTranslateX - previousTranslateX.value
						const cappedX = calculateDampedTranslateX(
							newTranslateX,
							previousTranslateX.value
						)
						const currentPos = translateX.value
						const th = calculateThresholds(maxSwipe.value)
						const isSwipingLeft = delta < 0
						const isNearThreshold =
							(currentPos >= th.smallerMin - THRESHOLD_PROXIMITY_BUFFER &&
								currentPos <=
									th.smallerThreshold + THRESHOLD_PROXIMITY_BUFFER) ||
							(currentPos >= th.maxMin - THRESHOLD_PROXIMITY_BUFFER &&
								currentPos <= th.maxMax + THRESHOLD_PROXIMITY_BUFFER)
						const inSmallerMargin =
							isNearThreshold &&
							currentPos >= th.smallerMin &&
							currentPos <= th.smallerThreshold
						const inMaxMargin =
							isNearThreshold &&
							((currentPos >= th.maxMin && currentPos <= th.maxMax) ||
								currentPos < th.maxThreshold)
						const pastSmaller =
							currentPos < th.smallerThreshold && !inSmallerMargin
						const towardsMax =
							isSwipingLeft &&
							pastSmaller &&
							currentPos < th.maxMin &&
							Math.abs(currentPos - th.maxThreshold) <
								Math.abs(previousTranslateX.value - th.maxThreshold)

						if ((inMaxMargin || towardsMax) && isSwipingLeft && !hasDelete) {
							hasTriggeredDelete.value = true
							lockToThreshold(
								th.maxThreshold,
								0,
								Math.max(48, Math.abs(th.maxThreshold) - 96)
							)
							runOnJS(onDelete)()
							return
						}

						if (
							inSmallerMargin &&
							!inMaxMargin &&
							isSwipingLeft &&
							!isLockedState &&
							!hasDelete
						) {
							const close =
								Math.abs(currentPos - th.smallerThreshold) <=
								LOCK_PROXIMITY_THRESHOLD
							const movingTowards =
								currentPos < previousTranslateX.value &&
								Math.abs(currentPos - th.smallerThreshold) <
									Math.abs(previousTranslateX.value - th.smallerThreshold)
							if (
								close &&
								movingTowards &&
								Math.abs(delta) < MAX_VELOCITY_FOR_LOCK
							) {
								lockToThreshold(th.smallerThreshold)
								return
							}
						}

						if (!hasDelete && !isLockedState) {
							translateX.value = cappedX
							previousTranslateX.value = cappedX
							updateButtonScales(cappedX)
						} else if (isLockedState) {
							const lockedCappedX = calculateDampedTranslateX(
								newTranslateX,
								previousTranslateX.value
							)
							translateX.value = lockedCappedX
							previousTranslateX.value = lockedCappedX
							updateButtonScales(lockedCappedX)
						}
					} else if (isLockedState && newTranslateX > startX.value) {
						translateX.value = newTranslateX
						previousTranslateX.value = newTranslateX
					}
				})
				.onEnd((event) => {
					const vx = event.velocityX
					const th = calculateThresholds(lockThreshold.value)
					const maxWidth = Math.max(48, Math.abs(th.maxThreshold) - 96)
					const estPos = vx < 0 ? translateX.value + vx * 0.1 : translateX.value
					const currentX = translateX.value
					const isLockedState = isLocked.value
					const hasDelete = hasTriggeredDelete.value
					const isSwipingLeft = vx < 0

					const inSmaller =
						(currentX >= th.smallerMin && currentX <= th.smallerThreshold) ||
						(estPos >= th.smallerMin && estPos <= th.smallerThreshold)
					const inMax =
						(currentX >= th.maxMin && currentX <= th.maxMax) ||
						(estPos >= th.maxMin && estPos <= th.maxMax) ||
						currentX < th.maxThreshold
					const inGap =
						isInGap(currentX, th.maxMin) || isInGap(estPos, th.maxMin)
					const pastSmaller = currentX <= th.smallerThreshold && !inSmaller
					const towardsMax =
						isSwipingLeft &&
						pastSmaller &&
						currentX < th.maxMin &&
						estPos < th.maxThreshold

					if (inGap && !isLockedState && !hasDelete && currentX < 0) {
						lockToThreshold(th.smallerThreshold, vx)
						return
					}

					if (
						(inMax || towardsMax) &&
						!isLockedState &&
						isSwipingLeft &&
						!hasDelete &&
						!inGap
					) {
						hasTriggeredDelete.value = true
						lockToThreshold(th.maxThreshold, vx, maxWidth)
						runOnJS(onDelete)()
						return
					}

					if (inSmaller && !inMax && !isLockedState && isSwipingLeft) {
						lockToThreshold(th.smallerThreshold, vx)
						return
					}

					const canLockToMax =
						((vx < VELOCITY_THRESHOLD &&
							currentX <= MIN_DISTANCE_FOR_VELOCITY_LOCK) ||
							currentX <= th.maxThreshold) &&
						!isLockedState &&
						!isInGap(currentX, th.maxMin)

					if (canLockToMax) {
						const shouldTriggerDelete =
							(vx < VELOCITY_THRESHOLD &&
								currentX <= MIN_DISTANCE_FOR_VELOCITY_LOCK) ||
							(currentX < th.smallerThreshold && !inSmaller)
						if (shouldTriggerDelete && !hasDelete) {
							hasTriggeredDelete.value = true
							lockToThreshold(th.maxThreshold, vx, maxWidth)
							runOnJS(onDelete)()
						} else {
							lockToThreshold(th.maxThreshold, vx, maxWidth)
						}
						return
					}

					const lockedPos = isLockedState
						? currentX <= th.smallerThreshold
							? th.smallerThreshold
							: th.maxThreshold
						: 0
					const shouldUnlock =
						(vx > -VELOCITY_THRESHOLD && isLockedState) ||
						(isLockedState && currentX > lockedPos / 2)

					if (shouldUnlock) {
						unlockAndReset(vx)
						return
					}

					if (isLockedState) {
						const pos = hasDelete
							? th.maxThreshold
							: currentX <= th.smallerThreshold
							? th.smallerThreshold
							: th.maxThreshold
						lockToThreshold(
							pos,
							vx,
							hasDelete
								? maxWidth
								: currentX <= th.smallerThreshold
								? 48
								: maxWidth
						)
					} else {
						unlockAndReset(vx)
					}
				}),
		[enabled, buttonId, onDelete]
	)

	return {
		panGesture,
		translateX,
		editButtonScale,
		deleteButtonScale,
		deleteButtonWidth,
		handleButtonLayout,
		resetToOriginalState
	}
}
